<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['penjaga']);require __DIR__.'/../../app/helpers/layout.php';render_start('Anggota','Data mahasiswa pengguna perpustakaan',$u);dashboard_nav('penjaga');render_mid('Anggota','Daftar anggota aktif dan nonaktif',$u);$rows=$pdo->query("SELECT u.* FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='pengguna' ORDER BY u.id DESC")->fetchAll();?><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>NIM</th><th>Nama</th><th>Kelas</th><th>Prodi</th><th>Semester</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nim'])?></td><td><?=e($r['name'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['study_program'])?></td><td><?=e($r['semester'])?></td><td><span class="badge <?=$r['status']==='aktif'?'green':'red'?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php render_end(); ?>
